<?php require_once 'config.php'; $pageTitle='Shop the farm'; $category=trim($_GET['category']??''); $search=trim($_GET['q']??''); $products=[]; $categories=[]; try{$categories=db()->query('SELECT * FROM categories ORDER BY name')->fetchAll(); $sql='SELECT p.*, c.name category FROM products p JOIN categories c ON c.id=p.category_id WHERE 1'; $params=[]; if($category){$sql.=' AND c.name=?';$params[]=$category;} if($search){$sql.=' AND (p.name LIKE ? OR p.description LIKE ?)';$params[]="%$search%";$params[]="%$search%";} $sql.=' ORDER BY p.featured DESC,p.created_at DESC';$stmt=db()->prepare($sql);$stmt->execute($params);$products=$stmt->fetchAll();}catch(Throwable $e){} include 'includes/header.php'; ?>
<section class="page-hero"><div class="container"><div class="eyebrow">The farm stand</div><h1>Good things,<br>grown close.</h1><p>Fresh eggs, healthy starts and the essentials that make caring for your flock feel simple.</p></div></section>
<section class="section"><div class="container shop-layout"><aside class="filters"><h3>Browse</h3><a class="<?= !$category?'active':'' ?>" href="shop.php">All products</a><?php foreach($categories as $item): ?><a class="<?= $category===$item['name']?'active':'' ?>" href="shop.php?category=<?= urlencode($item['name']) ?>"><?= e($item['name']) ?></a><?php endforeach; ?><hr><p>Every order is packed with care and prepared for local delivery.</p></aside><div><div class="shop-toolbar"><strong><?= count($products) ?> products</strong><form><input type="search" name="q" value="<?= e($search) ?>" placeholder="Search the farm..."><button class="btn btn-primary">Search</button></form></div><div class="product-grid"><?php foreach($products as $product): ?><article class="product-card"><a href="product.php?id=<?= (int)$product['id'] ?>"><div class="product-image <?= str_contains(strtolower($product['category']), 'egg')?'eggs':(str_contains(strtolower($product['category']),'feed')?'feed':'chicks') ?>"><img src="<?= e($product['image'] ?: 'https://images.unsplash.com/photo-1582722872445-44dc5f7e3c8f?auto=format&fit=crop&w=700&q=80') ?>" alt="<?= e($product['name']) ?>" width="700" height="500" loading="lazy"><span class="badge"><?= e(stock_message((int)$product['stock'])) ?></span></div></a><div class="product-info"><div class="rating">★★★★★ <span>(<?= e((string)$product['rating']) ?>)</span></div><h3><?= e($product['name']) ?></h3><p><?= e($product['description']) ?></p><div class="product-meta"><span class="price"><?= money($product['price']) ?></span><?php if($product['stock']>0): ?><button class="btn btn-outline" data-add-cart="<?= (int)$product['id'] ?>" data-csrf="<?= e(csrf_token()) ?>">Add to cart</button><?php else: ?><button class="btn btn-outline" disabled>Currently unavailable</button><?php endif; ?></div></div></article><?php endforeach; ?></div><?php if(!$products): ?><div class="empty-state"><div class="empty-icon">⌕</div><h3>No products found</h3><p>Try another search or browse the full farm collection.</p><a class="btn btn-primary" href="shop.php">View all products</a></div><?php endif; ?></div></div></section>
